```python
import numpy as np
from sklearn.linear_model import LinearRegression 

class InventoryManagement:
    def __init__(self):
        self.inventory = {} 
        self.sales_data = {} 

    def add_item(self, item, quantity):
        self.inventory[item] = quantity

    def record_sale(self, item, quantity):
        if item not in self.inventory or self.inventory[item] < quantity:
            print("Item not available in necessary quantity")
        else:
            self.inventory[item] -= quantity
            if item not in self.sales_data:
                self.sales_data[item] = [[0, quantity]]
            else:
                day, _ = self.sales_data[item][-1]
                self.sales_data[item].append([day + 1, quantity])

    def predict_restock(self, item, future_day):
        if item not in self.sales_data:
            print("Not enough historical data")
            return
        days, sales = zip(*self.sales_data[item])
        model = LinearRegression().fit(np.array(days).reshape(-1, 1), sales)
        prediction = model.predict(np.array(future_day).reshape(-1, 1))
        return max(0, int(prediction[0]))  # Predicted quantity to be sold

    def restock(self, item, quantity):
        if item not in self.inventory:
            self.inventory[item] = quantity
        else:
            self.inventory[item] += quantity
