A* algorithm is a powerful pathfinding method that utilizes a heuristic to guide the search towards the target node effectively. However, it requires all edge weights to be non-negative. To handle negative edges, we use Bellman-Ford algorithm to detect negative cycles. If the graph does not contain any negative cycles, we use Johnson's Algorithm to reweight all edges to non-negative while preserving the shortest path.

Here is a Python implementation of A* algorithm with Johnson's algorithm. We'll use `heapq` for the implementation of priority queue, `networkx` to manage graph and `numpy` for computing the heuristic.

```python
import heapq
import networkx as nx
import numpy as np

def heuristic(a, b):
    # Apply a suitable heuristic, such as Euclidean distance
    (x1, y1) = a
    (x2, y2) = b
    return abs(x1 - x2) + abs(y1 - y2)

def a_star(graph, start, goal):
    queue = [(0, start, [])]
    seen = set()
    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in seen:
            seen.add(node)
            path = path + [node]
            if node == goal:
                return (cost, path)
            for (next_node, edge_cost) in graph[node].items():
                if next_node not in seen:
                    total_cost = cost + edge_cost
                    priority = total_cost + heuristic(goal, next_node)
                    heapq.heappush(queue, (priority, next_node, path))
    return float("inf")

def johnson(graph):
    # Bellman-Ford
    dist = {node: 0 if node == "source" else float("inf") for node in graph.nodes}
    edges = [(u, v, data["weight"]) for u, v, data in graph.edges(data=True)]
    for _ in range(len(graph.nodes) - 1):  
        for u, v, weight in edges:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight

    # Detect negative cycles
    for u, v, weight in edges:
        if dist[v] > dist[u] + weight:
            raise ValueError("Negative cycle detected")

    # Reweight
    for u, v, data in graph.edges(data=True):
        data["weight"] += dist[u] - dist[v]

    # Perform A* on each pair of nodes
    for u, v in graph.edges():
        graph[u][v]["weight"] = a_star(graph, u, v)

    return graph

# Test code
G = nx.DiGraph()
G.add_edge(1, 2, weight=7)
G.add_edge(1, 3, weight=9)
G.add_edge(2, 3, weight=10)
G.add_edge(1, 6, weight=14)
G.add_edge(2, 4, weight=15)
G.add_edge(3, 4, weight=11)
G.add_edge(3, 6, weight=2)
G.add_edge(4, 5, weight=6)
G.add_edge(5, 6, weight=9)
johnson(G)
```
Please make sure that you have installed `networkx` by using pip such as `pip install networkx`.

This code firstly runs the Bellman-Ford algorithm to find the shortest path distances from an artificial source node to all other nodes. If a negative cycle is detected, it raises an error. Then, it reweights all edges such that all edge weights become non-negative while maintaining the shortest distances between all pairs of nodes. Finally, it applies the A* algorithm to each pair of nodes in the graph.

