To make a class representing a neural network in Python we can use the object-oriented features of Python. The basic architecture can be as follows:

```python
import numpy as np

# Define the activation functions
def sigmoid(x):
    return 1/(1 + np.exp(-x))

def sigmoid_derivative(x):
    return x * (1 - x)

# Define the Neural Network class
class NeuralNetwork:
    def __init__(self, layers):
        self.layers = layers
        self.weights = []
        self.biases = []

        # Initiate the weights and biases
        for i in range(len(layers) - 1):
            self.weights.append(np.random.randn(layers[i], layers[i + 1]))
            self.biases .append(np.random.randn(layers[i + 1]))

    def feedforward(self, X):
        self.a = [X]
        self.z = []

        for i in range(len(self.layers)-1):
            self.z.append(np.dot(self.a[i], self.weights[i]) + self.biases[i])
            self.a.append(sigmoid(self.z[-1]))
        return self.a[-1]

    def backpropagation(self, X, y, output, learning_rate=0.5):
        m = y.shape[0]
        self.dz = output - y
        self.dw = 1/m*np.dot(self.a[-2].T, self.dz)
        self.db = np.sum(self.dz, axis=0)/m

        self.weights[-1] -= learning_rate * self.dw
        self.biases[-1] -= learning_rate * self.db

        for i in range(len(self.layers)-3, -1, -1):
            self.dz = np.multiply(np.dot(self.dz, self.weights[i+1].T), sigmoid_derivative(self.a[i+1]))
            self.dw = 1/m*np.dot(self.a[i].T, self.dz)
            self.db = 1/m*np.sum(self.dz, axis=0)

            self.weights[i] -= learning_rate * self.dw
            self.biases[i] -= learning_rate * self.db

    def train(self, X, y, learning_rate=0.5, epochs=100):
        for _ in range(epochs):
            output = self.feedforward(X)
            self.backpropagation(X, y, output, learning_rate)

    def predict(self, X):
        return self.feedforward(X)
```

This class would represent a neural network with a variable number of layers. The weights and biases for each layer are stored in `self.weights` and `self.biases`, respectively. It has methods for forward propagation in the network `feedforward()`, back propagation `backpropagation()`, training the network `train()`, and prediction `predict()`. This class is scalable and can accommodate any number of hidden layers. You should adjust the learning rate, the number of epochs, and the activation functions as needed.

