```python
import sqlite3
import numpy as np

# Initialize the database
conn = sqlite3.connect('complex_matrix.db')
c = conn.cursor()

# Create the table for complex numbers and matrices if not exists
c.execute('''CREATE TABLE IF NOT EXISTS complex_numbers
             (name TEXT PRIMARY KEY, real NUMERIC, imaginary NUMERIC)''')

c.execute('''CREATE TABLE IF NOT EXISTS matrices
             (name TEXT PRIMARY KEY, matrix TEXT)''')


def add_to_db(name, value):
    if isinstance(value, np.ndarray):
        matrix_string = ','.join(map(str, value.flatten().tolist()))
        c.execute('''INSERT INTO matrices VALUES (?,?)''', (name, matrix_string))
    else:
        c.execute('''INSERT INTO complex_numbers VALUES (?,?,?)''', (name, float(value.real), float(value.imag)))
    conn.commit()


def get_from_db(name, is_matrix=False):
    if is_matrix:
        c.execute('''SELECT * FROM matrices WHERE name=?''', (name,))
        row = c.fetchone()
        matrix_list = list(map(float, row[1].split(',')))
        matrix = np.array(matrix_list).reshape(int(np.sqrt(len(matrix_list))), -1)
        return matrix
    else:
        c.execute('''SELECT * FROM complex_numbers WHERE name=?''', (name,))
        row = c.fetchone()
        return complex(float(row[1]), float(row[2]))


def perform_operation(op, a, b, is_matrix=False):
    if is_matrix:
        a = get_from_db(a, is_matrix=True)
        b = get_from_db(b, is_matrix=True)

        if op == 'add':
            return np.add(a, b)
        elif op == 'subtract':
            return np.subtract(a, b)
        elif op == 'multiply':
            return np.multiply(a, b)
        elif op == 'divide':
            return np.divide(a, b)
        elif op == 'determinant':
            return np.linalg.det(a)
        elif op == 'transpose':
            return np.transpose(a)
        else:
            return 'Invalid operation'
    else:
        a = get_from_db(a)
        b = get_from_db(b)

        if op == 'add':
            return a + b
        elif op == 'subtract':
            return a - b
        elif op == 'multiply':
            return a * b
        elif op == 'divide':
            return a / b
        else:
            return 'Invalid operation'


try:
    add_to_db('num1', complex(2, 3))
    add_to_db('num2', complex(4, -1))

